<?php
namespace App\Services; use App\Core\Database;use App\Core\Auth;
final class InvoiceService{public function create(array $d,array $items=[]):int{$pdo=Database::pdo();$pdo->beginTransaction();try{$subtotal=0;foreach($items as &$it){$it['quantity']=(float)($it['quantity']??1);$it['unit_price']=(float)($it['unit_price']??0);$it['total']=$it['quantity']*$it['unit_price'];$subtotal+=$it['total'];}unset($it);$tax=(float)($d['tax_amount']??0);$discount=(float)($d['discount']??0);$grand=max(0,$subtotal+$tax-$discount);$number=$d['invoice_number']??('INV-'.date('YmdHis').'-'.random_int(100,999));$s=$pdo->prepare('INSERT INTO invoices(tenant_id,invoice_number,client_id,business_id,project_id,created_date,due_date,status,sub_total,tax_amount,discount,grand_total,total_paid,balance,notes,created_by,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,NOW(),NOW())');$s->execute([$number,$d['client_id'],$d['business_id']?:null,$d['project_id']?:null,$d['created_date']??date('Y-m-d'),$d['due_date']?:null,$d['status']??'unpaid',$subtotal,$tax,$discount,$grand,0,$grand,$d['notes']??null,Auth::id()]);$id=(int)$pdo->lastInsertId();$i=$pdo->prepare('INSERT INTO invoice_items(invoice_id,description,quantity,unit_price,total) VALUES(?,?,?,?,?)');foreach($items as $it)$i->execute([$id,$it['description']??'Service',$it['quantity'],$it['unit_price'],$it['total']]);$pdo->commit();(new ActivityService)->record('INVOICE_CREATED','Billing','invoice',$id,null,'stage_2');return $id;}catch(\Throwable $e){$pdo->rollBack();throw $e;}}public function recordPayment(int $invoiceId,float $amount,string $method='other',string $reference=''):void{$pdo=Database::pdo();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT * FROM invoices WHERE id=? FOR UPDATE');$s->execute([$invoiceId]);$inv=$s->fetch();if(!$inv)throw new \RuntimeException('Invoice not found');$amount=min($amount,(float)$inv['balance']);if($amount<=0)throw new \InvalidArgumentException('No outstanding balance');$pdo->prepare('INSERT INTO invoice_payments(invoice_id,amount,payment_method,payment_date,reference_no,created_by,status) VALUES(?,?,?,?,?,?,?)')->execute([$invoiceId,$amount,$method,date('Y-m-d'),$reference,Auth::id(),'received']);$paid=(float)$inv['total_paid']+$amount;$bal=max(0,(float)$inv['grand_total']-$paid);$status=$bal<=0?'paid':($paid>0?'partial':'unpaid');$pdo->prepare('UPDATE invoices SET total_paid=?,balance=?,status=?,paid_date=IF(?<=0,CURDATE(),paid_date),updated_at=NOW() WHERE id=?')->execute([$paid,$bal,$status,$bal,$invoiceId]);$pdo->commit();(new ActivityService)->record('PAYMENT_RECEIVED','Billing','invoice',$invoiceId,['amount'=>$amount],'stage_2');}catch(\Throwable $e){$pdo->rollBack();throw $e;}}}
